def apply(inputs, premises):
    descriptions = inputs["asset_descriptions"]
    values = inputs["asset_values"]
    asset_types = inputs["asset_types"]
    debtor_count = int(inputs["debtor_count"])
    answer = {}
    for i in range(len(descriptions)):
        claims = []
        asset_value = float(values[i])
        for j in range(len(premises["rule_citations"])):
            applicable = premises["rule_protected_types"][j] == "any" or premises["rule_protected_types"][j] == asset_types[i]
            if applicable:
                if inputs["output_family"] == "EC":
                    claims = claims + [premises["rule_citations"][j]]
                else:
                    cap = float(premises["rule_base_caps"][j])
                    if premises["rule_per_debtor"][j]:
                        cap = cap * debtor_count
                    if cap < 0:
                        claim_value = asset_value
                    else:
                        claim_value = min(asset_value, cap)
                    claims = claims + [{"citation": premises["rule_citations"][j], "claim_value": claim_value}]
        answer[descriptions[i]] = claims
    return {"answer": answer}

